import{_ as a,o as i,c as t,a as n}from"./app.DLiRGumz.js";const u=JSON.parse('{"title":"Planning Simulation & Replay Sandbox Depth (WP-4007, WP-12004)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/SIMULATION_AND_SANDBOX_DEPTH.md","filePath":"reference/SIMULATION_AND_SANDBOX_DEPTH.md","lastUpdated":1771753292000}'),s={name:"reference/SIMULATION_AND_SANDBOX_DEPTH.md"};function o(l,e,r,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="planning-simulation-replay-sandbox-depth-wp-4007-wp-12004" tabindex="-1">Planning Simulation &amp; Replay Sandbox Depth (WP-4007, WP-12004) <a class="header-anchor" href="#planning-simulation-replay-sandbox-depth-wp-4007-wp-12004" aria-label="Permalink to &quot;Planning Simulation &amp; Replay Sandbox Depth (WP-4007, WP-12004)&quot;">​</a></h1><p>This document provides technical depth for the <strong>Simulation Engine</strong> and <strong>Replay Sandbox</strong>, enabling &quot;What-if&quot; analysis and pre-flight verification without mutating real-world state.</p><h2 id="_1-virtual-state-isolation-the-sandbox" tabindex="-1">1. Virtual State Isolation (The Sandbox) <a class="header-anchor" href="#_1-virtual-state-isolation-the-sandbox" aria-label="Permalink to &quot;1. Virtual State Isolation (The Sandbox)&quot;">​</a></h2><p>Simulations must run in a &quot;No-Side-Effect&quot; environment. <code>thegent</code> uses a multi-layered isolation strategy:</p><h3 id="_1-1-virtual-file-system-vfs" tabindex="-1">1.1 Virtual File System (VFS) <a class="header-anchor" href="#_1-1-virtual-file-system-vfs" aria-label="Permalink to &quot;1.1 Virtual File System (VFS)&quot;">​</a></h3><p>For tools that modify the file system (e.g., <code>Write</code>, <code>StrReplace</code>, <code>delete_file</code>), the simulation engine injects a <code>VirtualFileSystem</code> layer:</p><ul><li><strong>Copy-on-Write (CoW)</strong>: The simulation reads from the real FS but writes to an in-memory <code>OverlayFS</code>.</li><li><strong>Isolation</strong>: No simulation write ever touches the real disk.</li><li><strong>Diff Generation</strong>: The engine compares the <code>OverlayFS</code> with the real FS to generate a &quot;Predicted Change Manifest.&quot;</li></ul><h3 id="_1-2-tool-side-effect-mocking" tabindex="-1">1.2 Tool Side-Effect Mocking <a class="header-anchor" href="#_1-2-tool-side-effect-mocking" aria-label="Permalink to &quot;1.2 Tool Side-Effect Mocking&quot;">​</a></h3><p>Every tool in the <code>thegent</code> registry must define a <code>simulate()</code> method or a <code>dry_run</code> behavior:</p><ul><li><strong>Read-Only Tools</strong>: Execute as normal (safe).</li><li><strong>Mutating Tools</strong>: Return a &quot;Mock Result&quot; (e.g., <code>git commit</code> returns a dummy hash; <code>gh pr create</code> returns a placeholder URL).</li><li><strong>Side-Effect Schema</strong>:<div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ToolSideEffect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BaseModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tool_id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    action: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    impacted_resources: list[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    predicted_result: Any</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    reversibility: Literal[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;atomic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manual&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;irreversible&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div></li></ul><h2 id="_2-probabilistic-planning-monte-carlo-pert" tabindex="-1">2. Probabilistic Planning (Monte Carlo / PERT) <a class="header-anchor" href="#_2-probabilistic-planning-monte-carlo-pert" aria-label="Permalink to &quot;2. Probabilistic Planning (Monte Carlo / PERT)&quot;">​</a></h2><p>For complex multi-agent DAGs, the simulation engine provides schedule risk quantification.</p><h3 id="_2-1-pert-uncertainty-wp-8002" tabindex="-1">2.1 PERT Uncertainty (WP-8002) <a class="header-anchor" href="#_2-1-pert-uncertainty-wp-8002" aria-label="Permalink to &quot;2.1 PERT Uncertainty (WP-8002)&quot;">​</a></h3><p>Instead of a single duration, each node in the DAG carries:</p><ul><li><code>t_optimistic</code> (O)</li><li><code>t_most_likely</code> (M)</li><li><code>t_pessimistic</code> (P)</li><li><strong>Calculated Duration</strong>: <code>T = (O + 4M + P) / 6</code></li></ul><h3 id="_2-2-monte-carlo-simulation" tabindex="-1">2.2 Monte Carlo Simulation <a class="header-anchor" href="#_2-2-monte-carlo-simulation" aria-label="Permalink to &quot;2.2 Monte Carlo Simulation&quot;">​</a></h3><p>The engine runs N=1000 iterations of the DAG, sampling from the PERT distributions to produce:</p><ul><li><strong>P50 (Median)</strong>: 50% chance of completion by this time.</li><li><strong>P80 (Target)</strong>: 80% confidence band (the standard for commitment).</li><li><strong>P95 (Safe)</strong>: 95% confidence band (includes worst-case jitter).</li></ul><h2 id="_3-what-if-scenario-branching-wp-12004" tabindex="-1">3. What-if Scenario Branching (WP-12004) <a class="header-anchor" href="#_3-what-if-scenario-branching-wp-12004" aria-label="Permalink to &quot;3. What-if Scenario Branching (WP-12004)&quot;">​</a></h2><p>Operators can &quot;Fork&quot; an execution at any decision node:</p><ol><li><strong>Checkpoint Capture</strong>: Save the <code>RunState</code> and <code>Context</code> at node N.</li><li><strong>Alternative Input</strong>: Inject a different agent response or tool result.</li><li><strong>Shadow Execution</strong>: Run the remainder of the DAG in the <strong>Replay Sandbox</strong>.</li><li><strong>Outcome Comparison</strong>: The Cockpit displays a side-by-side &quot;Baseline vs. What-if&quot; outcome.</li></ol><h2 id="_4-pre-flight-verification" tabindex="-1">4. Pre-flight Verification <a class="header-anchor" href="#_4-pre-flight-verification" aria-label="Permalink to &quot;4. Pre-flight Verification&quot;">​</a></h2><p>Irreversible actions (e.g., <code>git push --force</code>, <code>rm -rf</code>) trigger a mandatory simulation:</p><ul><li><strong>Policy Gate</strong>: The <code>PolicyEngine</code> evaluates the &quot;Predicted Change Manifest.&quot;</li><li><strong>Visual Preview</strong>: The operator sees a diff of all files that <em>would</em> be changed and a list of all tools that <em>would</em> be called.</li><li><strong>Commitment</strong>: Only after simulation success and operator sign-off is the &quot;Sandbox Lock&quot; released for real execution.</li></ul><hr><p><em>Cross-ref: <a href="./PHASE_4_COCKPIT_UX_DEPTH.html">PHASE_4_COCKPIT_UX_DEPTH.md</a> | <a href="./../plans/03-UNIFIED-DAG.html">03-UNIFIED-DAG.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>`,38)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
